def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 70
    supply = day_context['supply']
    hp = my_status['hp']
    budget = my_status['budget']
    no_water = my_status['no_water_days']

    alive_opponents = []
    prev_bids = []
    opp_requirements = []
    for opp in opponents_status.values():
        if opp.get('alive'):
            alive_opponents.append(opp)
            opp_requirements.append(opp.get('water_requirement', WATER_REQ))
            prev = opp.get('previous_trace', {})
            bid = prev.get('bid') if prev else None
            if bid is not None:
                prev_bids.append(bid)

    if budget <= 0:
        return 0.0

    if not alive_opponents:
        safe_bid = DAILY_SALARY * 0.25
        if hp <= 2 or no_water >= 2:
            safe_bid = DAILY_SALARY * 0.6
        return float(min(budget, safe_bid))

    total_agents = 1 + len(alive_opponents)
    total_req = WATER_REQ
    for req in opp_requirements:
        total_req += req

    scarcity = supply < total_req
    severe_scarcity = supply <= max(WATER_REQ, 15)

    highest_prev = max(prev_bids) if prev_bids else 0.0
    avg_prev = sum(prev_bids) / len(prev_bids) if prev_bids else 0.0

    danger = 0
    if hp <= 2:
        danger += 3
    elif hp <= 4:
        danger += 2
    elif hp <= 6:
        danger += 1

    if no_water >= 2:
        danger += 3
    elif no_water >= 1:
        danger += 1

    if severe_scarcity:
        danger += 2
    elif scarcity:
        danger += 1

    if highest_prev >= 90:
        if danger >= 5:
            bid = 96.0
        elif danger >= 3:
            bid = 78.0
        else:
            bid = 46.0
    elif highest_prev >= 75:
        if danger >= 5:
            bid = highest_prev + 4.0
        elif danger >= 3:
            bid = highest_prev + 1.5
        else:
            bid = 52.0
    elif highest_prev > 0:
        if danger >= 5:
            bid = max(72.0, highest_prev + 3.0)
        elif danger >= 3:
            bid = max(58.0, avg_prev + 2.0)
        else:
            bid = max(40.0, avg_prev * 0.75)
    else:
        if danger >= 5:
            bid = 75.0
        elif danger >= 3:
            bid = 58.0
        else:
            bid = 42.0

    if supply >= 24:
        bid -= 8.0
    elif supply >= 20:
        bid -= 4.0
    elif supply <= 16:
        bid += 6.0

    if hp >= 8 and no_water == 0 and highest_prev >= 90:
        bid = min(bid, 44.0)

    reserve_floor = DAILY_SALARY * 0.35
    if budget < bid:
        bid = budget
    elif budget - bid < reserve_floor and danger < 4:
        bid = max(0.0, budget - reserve_floor)

    if danger >= 5:
        bid = max(bid, min(budget, 82.0))

    if bid < 0:
        bid = 0.0
    return float(min(budget, bid))

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 9
    DAILY_SALARY = 90
    MAX_SUPPLY = 25
    MIN_SUPPLY = 15

    supply = float(day_context['supply'])
    day = int(day_context['day'])

    # Identify alive opponents
    alive_opps = []
    for oid, o in opponents_status.items():
        if o.get('alive', False):
            alive_opps.append((oid, o))

    # If no opponents alive, bid conservatively
    if not alive_opps:
        cap = min(my_status['budget'], DAILY_SALARY * 0.4)
        return float(cap)

    # Use only yesterday's previous_trace bid for each opponent for immediate reaction
    prev_bids = []
    for oid, o in alive_opps:
        prev = o.get('previous_trace', {}) or {}
        b = prev.get('bid', None)
        if b is not None:
            try:
                prev_bids.append(float(b))
            except Exception:
                pass

    # Defaults based on our health/budget
    hp = float(my_status['hp'])
    budget = float(my_status['budget'])

    # Estimate pressure from yesterday
    highest_prev_bid = max(prev_bids) if prev_bids else 0.0
    second_prev_bid = sorted(prev_bids)[-2] if len(prev_bids) >= 2 else (prev_bids[0] if prev_bids else 0.0)

    # Supply-aware aggressiveness: closer to max supply => more likely to allow higher bids; bid just above typical leader
    supply_ratio = 0.0
    if MAX_SUPPLY > MIN_SUPPLY:
        supply_ratio = (supply - MIN_SUPPLY) / (MAX_SUPPLY - MIN_SUPPLY)
    supply_ratio = max(0.0, min(1.0, supply_ratio))

    # Target bid baseline
    # If Cindy-like high pressure existed yesterday, we must match/beat slightly.
    if highest_prev_bid >= DAILY_SALARY * 0.9:
        # Cindy was very aggressive; if our hp is low, bid more to guarantee water.
        if hp <= 2.0:
            target = DAILY_SALARY * (0.95 - 0.15 * supply_ratio)
        else:
            # Slightly above the second-highest to avoid tying into a loss
            target = max(second_prev_bid + 2.0, DAILY_SALARY * (0.65 + 0.15 * supply_ratio))
    else:
        # Moderate pressure: bid around Alex-like level, scaled by supply.
        # Use highest_prev_bid as an anchor but don't overpay.
        anchor = highest_prev_bid if highest_prev_bid > 0 else (DAILY_SALARY * 0.55)
        target = max(DAILY_SALARY * (0.45 + 0.2 * supply_ratio), min(anchor + 5.0, DAILY_SALARY * 0.75))

    # If our budget is tight, scale down
    if budget < DAILY_SALARY * 0.6:
        target = min(target, budget * 0.9)

    # If hp is critical, spend more (but never exceed budget)
    if hp <= 1.5:
        target = min(budget, max(target, DAILY_SALARY * 0.9))

    bid = min(budget, target)
    if bid < 0.0:
        bid = 0.0
    return float(bid)

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 7
    DAILY_SALARY = 80
    supply = day_context['supply']
    alive_opponents = [o for o in opponents_status.values() if o['alive']]

    yesterday_bids = []
    for opp in alive_opponents:
        prev = opp.get('previous_trace', {})
        if prev and prev.get('bid') is not None:
            yesterday_bids.append(prev['bid'])

    if not alive_opponents:
        return float(min(my_status['budget'], 20.0))

    max_prev = max(yesterday_bids) if yesterday_bids else 50.0

    if my_status['hp'] <= 3:
        return float(min(my_status['budget'], max(max_prev + 5.0, 75.0)))

    if supply < (len(alive_opponents) + 1) * WATER_REQ:
        return float(min(my_status['budget'], max_prev + 2.0))

    return float(min(my_status['budget'], max(40.0, max_prev * 0.95)))
